import fs from "node:fs"

const source = JSON.parse(fs.readFileSync(new URL("../src/design-system/rules.json", import.meta.url), "utf8"))
const lines = [
  `# OneDS ${source.title}`,
  "",
  "Generated from src/design-system/rules.json. Do not edit this file directly.",
  "",
  source.description,
  "",
  source.adoption,
  "",
]

for (const status of ["approved", "candidate"]) {
  lines.push(`## ${status === "approved" ? "Approved Rules" : "Under Exploration"}`, "")
  for (const rule of source.rules.filter(rule => rule.status === status)) {
    lines.push(
      `### ${rule.title}`,
      "",
      `ID: ${rule.id} | ${rule.section} | ${rule.level} | ${rule.status}`,
      "",
      rule.rule,
      "",
      `Why: ${rule.why}`,
      "",
      `Exceptions: ${rule.exceptions}`,
      "",
      `Decision evidence: ${rule.evidence}`,
      "",
      `Enforcement: ${rule.enforcement.kind}. ${rule.enforcement.detail}`,
      "",
      ...(rule.tokens.length ? [`Tokens: ${rule.tokens.map(token => `\`${token}\``).join(", ")}`, ""] : []),
      `Implementation: ${rule.implementation.map(file => `[${file}](../${file})`).join(", ")}`,
      "",
    )
  }
}

const output = `${lines.join("\n").trimEnd()}\n`
const target = new URL("../public/design-rules.md", import.meta.url)
if (process.argv.includes("--check")) {
  if (!fs.existsSync(target) || fs.readFileSync(target, "utf8") !== output) {
    console.error("Design rules Markdown is stale. Run npm run rules:generate.")
    process.exitCode = 1
  }
} else {
  fs.writeFileSync(target, output)
  console.log(`Generated ${source.rules.length} design rules.`)
}